WITH recent_shipments AS (SELECT *, DATEDIFF(delivered_date, shipped_date) AS days_shipped_date_to_delivered_date FROM shipments WHERE status IN ('LOST', 'IN_TRANSIT', 'DELIVERED')), summary AS (SELECT CASE WHEN carrier IN ('Flash', 'Kerry') THEN 'tier_1' ELSE 'other' END AS carrier_group, SUM(CASE WHEN status = 'RETURNED' THEN cost ELSE 0 END) AS returned_cost, SUM(cost) AS total_cost FROM recent_shipments GROUP BY CASE WHEN carrier IN ('Flash', 'Kerry') THEN 'tier_1' ELSE 'other' END) SELECT * FROM summary;
